 SelectionKind.ClosedPlanarCurve=>new[]{A("solidextrude","⬒","Extrudieren und schließen","_ExtrudeCrv _Solid=_Yes","Geschlossenen Körper erzeugen","Erzeugen"),A("planarsrf","▰","Fläche erzeugen","_PlanarSrf","Planare Fläche erzeugen","Erzeugen"),A("pipe","◉","Rohr erzeugen","_Pipe","Rohr erzeugen","Erzeugen"),A("offset","⇆","Kurve versetzen","_Offset","Kurve versetzen")},
 SelectionKind.Curve=>new[]{A("offset","⇆","Kurve versetzen","_Offset","Kurve versetzen"),A("pipe","◉","Rohr erzeugen","_Pipe","Rohr erzeugen","Erzeugen"),A("rebuild","⟳","Neu aufbauen","_Rebuild","Kurve neu aufbauen")},
 SelectionKind.PlanarBrepFace or SelectionKind.BrepFace=>new[]{A("inset","▣","Inset","_Inset","Inset erzeugen"),A("moveface","✥","Fläche verschieben","_MoveFace","Teilfläche verschieben"),A("extractsrf","⇱","Fläche lösen","_ExtractSrf","Teilfläche lösen"),A("deleteface","⌫","Fläche löschen","_Delete","Teilfläche löschen","Kritisch",true)},
 SelectionKind.PlanarSurface or SelectionKind.Surface=>new[]{A("inset","▣","Inset","_Inset","Inset erzeugen"),A("offsetsrf","⇆","Fläche versetzen","_OffsetSrf","Fläche versetzen"),A("extrudesrf","⇧","Fläche extrudieren","_ExtrudeSrf","Fläche extrudieren","Erzeugen")},
 SelectionKind.SolidBrep=>new[]{A("union","∪","Vereinigen","_BooleanUnion","Körper vereinigen","Bearbeiten",false,"Multiple"),A("difference","−","Differenz bilden","_BooleanDifference","Körper abziehen","Kritisch",true,"Multiple"),A("fillet","⌒","Kanten abrunden","_FilletEdge","Kanten abrunden")},
 SelectionKind.Brep=>new[]{A("explode","⤢","Zerlegen","_Explode","Flächenverband zerlegen","Kritisch",true),A("merge","▤","Coplanare Flächen vereinigen","_MergeAllCoplanarFaces","Coplanare Flächen vereinigen","Bearbeiten",false,"Coplanar"),A("cap","▰","Öffnungen schließen","_Cap","Planare Öffnungen schließen","Bearbeiten",false,"Open")},
 SelectionKind.Mesh=>new[]{A("reduce","▽","Mesh reduzieren","_ReduceMesh","Polygonzahl reduzieren"),A("quad","▦","Quad-Mesh erzeugen","_QuadRemesh","Quad-Mesh erzeugen","Konvertieren"),A("check","✓","Mesh prüfen","_Check","Mesh prüfen","Analyse")},
 SelectionKind.SubD=>new[]{A("extrudesubd","⇧","SubD extrudieren","_ExtrudeSubD","SubD extrudieren"),A("insertedge","＋","Kante einsetzen","_InsertEdge","Kante einsetzen"),A("crease","⌁","Schärfen","_Crease","Kante schärfen")},
 SelectionKind.Block=>new[]{A("unique","◆","Einzigartigen Block erstellen","_CreateUniqueBlock","Eigene Definition erzeugen","Block"),A("edit","✎","Block bearbeiten","_BlockEdit","Definition bearbeiten","Block"),A("replace","⇄","Block ersetzen","_ReplaceBlock","Definition ersetzen","Block",false,"OtherBlocks"),A("selectsame","▦","Gleiche Blöcke auswählen","_SelBlockInstanceNamed","Gleiche Definition auswählen","Block"),A("manager","☷","Blockmanager öffnen","_BlockManager","Blockdefinitionen verwalten","Block"),A("add","＋","Objekte zum Block hinzufügen","_AddObjectsToBlock","Objekte ergänzen","Block"),A("resetscale","1:1","Blockmaßstab zurücksetzen","_BlockResetScale","Skalierung zurücksetzen","Block"),A("explodeblock","⤢","Block vollständig zerlegen","_ExplodeBlock","Block und Unterblöcke zerlegen","Kritisch",true)},
 SelectionKind.Multiple or SelectionKind.Mixed=>new[]{A("group","▦","Gruppieren","_Group","Objekte gruppieren"),A("align","≡","Ausrichten","_Align","Objekte ausrichten"),A("join","⛓","Verbinden","_Join","Objekte verbinden")},
 _=>Array.Empty<ContextAction>()};
}
